CREATE TABLE IF NOT EXISTS deduplicated_reagents AS
SELECT DISTINCT CAS, REAGENT_NAME, OTHER_COLUMNS 
FROM reagent_catalog;

CREATE TABLE IF NOT EXISTS deduplicated_reagents AS
SELECT DISTINCT CAS, REAGENT_NAME, OTHER_COLUMNS 
FROM reagents;

CREATE TABLE IF NOT EXISTS deduplicated_reagents AS
SELECT DISTINCT cas_number, name, quantity, location, notes 
FROM reagents;

INSERT INTO shared_export (recipient_org, data)
SELECT 'lab_inventory', json_group_array(json_object('cas_number', cas_number, 'name', name, 'quantity', quantity, 'location', location, 'notes', notes))
FROM deduplicated_reagents;

INSERT INTO shared_export (recipient_org, payload)
SELECT 'lab_inventory', json_group_array(json_object('cas_number', cas_number, 'name', name, 'quantity', quantity, 'location', location, 'notes', notes))
FROM deduplicated_reagents;

UPDATE shared_export
SET payload = json_group_array(json_object('cas_number', cas_number, 'name', name, 'quantity', quantity, 'location', location, 'notes', notes))
WHERE recipient_org='lab_inventory';

DROP TABLE IF EXISTS temp_reagents;
CREATE TABLE temp_reagents AS
SELECT DISTINCT cas_number, name, quantity, location, notes 
FROM deduplicated_reagents;

SELECT json_group_array(json_object('cas_number', cas_number, 'name', name, 'quantity', quantity, 'location', location, 'notes', notes))
FROM temp_reagents;
